"""Generate the Home and About pages. Single source of truth: run this module, commit the HTML.

  python3 layout_atlas/navigation.py

Counts and licences come from data/atlas_registry.json.
"""
import html
import json
from pathlib import Path
from core import ROOT
import ui
REG = ROOT / 'data' / 'atlas_registry.json'
def _registry():
    return json.loads(REG.read_text())

def _fmt(n):
    return f'{int(n):,}'
HOME_CSS = '<style>.hero{padding:18px 0 8px}.hero h1{font-size:clamp(28px,5vw,44px)}.cta{display:inline-block;background:var(--accent);color:var(--accent-ink);padding:12px 26px;border-radius:999px;text-decoration:none;font-weight:600;font-size:17px;margin:6px 10px 6px 0}.cta.alt{background:var(--soft);color:var(--ink)}.steps3{display:grid;grid-template-columns:repeat(auto-fit,minmax(230px,1fr));gap:16px;margin:24px 0}.steps3 .card b{display:block;color:var(--accent);font-size:13px;letter-spacing:.06em;text-transform:uppercase}.steps3 .card h3{margin:4px 0}</style>'
TOOL = 'layout_atlas/results/tool/index.html'

def home():
    b = ui.bi
    steps = ''.join((f'<div class="card"><b>{n}</b><h3>{b(t)}</h3><p class="meta">{b(d)}</p></div>' for n, t, d in [('1', 'Choose a model', 'Upload an SBML (.xml) or BiGG/COBRA (.json) genome-scale model, or pick an example: e_coli_core, iIT341, iMM904 or iML1515.'), ('2', 'Generate', 'One click. Matched Atlas structures keep their curated geometry; every other reaction is completed with Bézier connections. All reactions and metabolites of your model are kept.'), ('3', 'Download', 'Get the complete map as editable SVG or Escher JSON, with per-reaction provenance and licence metadata.')]))
    body = HOME_CSS + f'<div class="hero"><a class="cta" href="{TOOL}">' + b('Open the Map Generator') + f'</a><a class="cta alt" href="layout_atlas/results/about/index.html">' + b('About and data provenance') + '</a></div><div class="steps3">' + steps + '</div><div class="note">' + b('Result details on the result page report, for each reaction, whether its geometry was reused from a curated community map, only guided by topology or EC, or generated by the algorithm. The Atlas behind this is described under About / Provenance.') + '</div>'
    lead = b('Upload a genome-scale metabolic model and get a complete, readable and editable metabolic map, drawn from public community pathway layouts where they fit.')
    ui.write(ROOT / 'index.html', 'Open Meta Maps', body, section='home', lead=lead)

def about():
    e = html.escape
    b = ui.bi
    reg = _registry()
    oc = reg['open_core']
    ext = reg['extensions']
    mods = oc['modules_with_extensions']
    total = sum(mods.values())
    core_sum = sum(oc['modules'].values())
    version = '0.3'
    try:
        version = str(json.loads((Path(__file__).parent / 'config.json').read_text()).get('version') or version)
    except Exception:
        pass

    def sec(t, inner):
        return f'<section class="panel"><h2>{b(t)}</h2>{inner}</section>'
    s1 = sec('About Open Meta Maps', '<p><b>' + b('Collect public community-drawn pathway layouts, reuse them for a genome-scale model, and complete the rest algorithmically.') + '</b></p><p>' + b('Open Meta Maps is ELIXIR BioHackathon Europe 2026 Project 22 (Open Pathway Maps). The Atlas stores reusable structures extracted from community-drawn maps; the Layout Composer matches them to an uploaded GEM, keeps curated geometry where it fits, and places every remaining reaction. Layout benchmarks and the evaluation CLI are development aids, not the project goal.') + '</p>')
    steps = [('1', 'Build the Atlas', 'Pathway structures (topology, reaction identity, geometry, licence) are extracted from public community maps and stored with provenance.'), ('2', 'Match and transfer', 'For an uploaded model, matching structures are retrieved; exact matches, topology-only references and optional EC suggestions are kept clearly apart.'), ('3', 'Complete with Bézier layout', 'Reactions without reusable curated geometry are placed by the algorithm; Bézier connections, labels and layout-quality checks follow. Nothing from the model is dropped.')]
    s2 = sec('How it works', '<div class="steps3">' + ''.join((f'<div class="card"><b>{n}</b><h3>{b(tt)}</h3><p class="meta">{b(d)}</p></div>' for n, tt, d in steps)) + '</div><p>' + b('Every generated map passes an integrity check that reactions, stoichiometry and compartments are preserved. That check is not a validation of the biological correctness of the model.') + '</p>')
    by_line = ' · '.join((f'{k} {_fmt(v)}' for k, v in [('escher', mods['escher']), ('reactome', mods['reactome']), ('wikipathways', mods['wikipathways'] + mods['wikipathways_geometry']), ('human_maps', mods['human_maps']), ('brenda', mods['brenda']), ('metabolismregulation', mods['metabolismregulation']), ('panther', mods['panther'])]))
    s3 = sec('The Atlas', '<div class="stats">' + ui.stat(_fmt(total), 'module structures (default Atlas)') + ui.stat(_fmt(core_sum), 'open-core SQLite modules') + ui.stat(_fmt(oc['reactions']), 'reactions in open-core') + '</div><p class="meta">' + b('Default Atlas module counts by source (open-core SQLite plus default extensions; from data/atlas_registry.json):') + ' <span class="dn">' + e(by_line) + '</span></p><p class="meta">' + b('WikiPathways appears as semantic modules in open_core.sqlite plus a geometry-only extension kept separate for repository size; both load by default.') + '</p>')

    def row(*cells):
        return '<tr>' + ''.join((f'<td>{c}</td>' for c in cells)) + '</tr>'
    th = ''.join((f'<th>{b(h)}</th>' for h in ['Source', 'What is used', 'Modules', 'Licence', 'Status']))
    dflt = b('Used by default')
    wp_mods = mods['wikipathways'] + mods['wikipathways_geometry']
    tbl = '<div class="tablewrap"><table><thead><tr>' + th + '</tr></thead><tbody>' + row('Escher', b(f"{oc['maps']['escher']} community maps"), _fmt(mods['escher']), 'CC0-1.0', dflt) + row('Reactome', b(f"release 97 · {oc['maps']['reactome']} diagrams"), _fmt(mods['reactome']), 'CC0 (data)', dflt) + row('WikiPathways', b(f"release 20261110 · {oc['maps']['wikipathways']} maps; {_fmt(mods['wikipathways'])} semantic + {_fmt(mods['wikipathways_geometry'])} geometry-only modules"), _fmt(wp_mods), 'CC0-1.0', dflt) + row('Human-maps', b(f"{ext['human_maps']['maps']} official Escher JSON maps (SVG/BY-SA not imported)"), _fmt(mods['human_maps']), 'CC BY 4.0', dflt) + row('BRENDA', b(f"{ext['brenda']['pathways']} pathway maps; layout possibly automatic"), _fmt(mods['brenda']), 'CC BY 4.0', dflt) + row('Metabolism Regulation', b(f"{ext['metabolismregulation']['maps']} SBGN-ML gallery maps (hand-drawn)"), _fmt(mods['metabolismregulation']), 'CC BY 4.0', dflt) + row('PANTHER', b(f"version {ext['panther']['version']} · {ext['panther']['maps']} CellDesigner maps"), _fmt(mods['panther']), 'CC BY 4.0', dflt) + '</tbody></table></div>'
    s4 = sec('Data sources and licensing', tbl + '<p>' + b('MicroMap and Yeast-maps are not included. KEGG is not an Atlas source. Full attribution: THIRD_PARTY_NOTICES.md. Evidence notes: docs/licensing_audit.md.') + '</p><p>' + b('The software is MIT (LICENSE). The default Atlas mixes CC0 and CC BY 4.0 sources, so the Atlas and maps generated from it are distributed under CC BY 4.0; reuse must keep the attributions in THIRD_PARTY_NOTICES.md.') + '</p>')
    s5 = sec('Matching and layout defaults', '<ul><li>' + b('Matching uses EC currentisation (ExPASy), Rhea metabolite scoring for EC disambiguation, name normalisation, weighted Jaccard (currency metabolites half-weighted), and vicinity propagation for BRENDA. Details: docs/reaction_map_matching.md.') + '</li><li>' + b('EC similarity extension is optional and off by default (CLI --ec; Map Generator checkbox). Recommendation: docs/ec_extension_recommendation.md.') + '</li><li>' + b('Layout default is Bézier / layout_style=curated (the former name expert remains accepted as a deprecated alias). Orthogonal libavoid remains available only as CLI --layout-style legacy.') + '</li><li>' + b('Map Generator: python3 project.py tool or ./start_tool.command. Examples: e_coli_core, iIT341, iMM904, iML1515. Viewer supports pan, wheel/pinch zoom and a minimap. The server exits when the last browser tab closes (grace ~8 s); pass --keep-running to disable.') + '</li><li>' + b('Layout evaluation CLI (development aid): pip install -r layout_atlas/requirements-eval.txt, then python3 project.py evaluate --gem MODEL.xml --map DIR/map.json. See docs/layout_evaluation.md.') + '</li></ul>')
    s5b = sec('Layout after curated reuse', '<p>' + b('After matching, the Composer keeps curated blocks rigid, completes uncovered reactions, orients free reactions, composes stray components, draws Bézier connections and places labels. Full stage table and layout rule status: README (Layout after curated reuse).') + '</p><ul><li>' + b('Rigid skeleton and completion: drawing.pack_modules, completion.complete_spaced, completion_context.place, instances.optimize (currency stays private side glyphs).') + '</li><li>' + b('Orientation, composition, peripherals: orientation.apply (default full); composition.compose and peripheral.attach on; whole-block relocation off unless OPM_BLOCK_RELOC=on.') + '</li><li>' + b('Bézier curated style (edge_style.apply), optional --source-paths; labels via label_placement.optimize; integrity via tool_pipeline.check_integrity.') + '</li><li>' + b('Layout rules (crossings, overlaps, long edges, participant consistency, compartments, compactness, reproducibility, scale): mostly partial; compartment respect and build-on-previous-layout not yet product goals. Gaps: 2D component packing, harder orientation, compose --seed.') + '</li></ul>')
    s6 = sec('Reproducibility', '<p>' + b('Every result contains:') + '</p><ul><li><b>' + b('Reaction provenance') + '</b>: ' + b('curated (community layout), topology-only suggestion, functional (EC) suggestion, bridge or generated, with matching evidence') + '</li><li><b>' + b('Layout quality') + '</b></li><li><b>' + b('Generation settings') + '</b></li><li><b>' + b('Licensing metadata') + '</b> (<code>licenses.json</code>)</li></ul><p>' + b('Curated-geometry reuse, topology-only references and EC suggestions are reported separately and never merged into one reuse rate.') + '</p><p class="meta">' + b('Report files') + ': <code>report.json</code> · <code>reaction_provenance.json</code> · <code>licenses.json</code> · ' + b('Software version') + f': v{e(version)} · ' + b('Registry generated') + f': {e(reg.get("generated", ""))}</p>')
    about_path = ROOT / 'layout_atlas' / 'results' / 'about' / 'index.html'
    cards = ''.join((f'<a class="card" href="{ui.rel(about_path, path)}" style="text-decoration:none"><h3>{b(en)}</h3></a>' for en, path in [('Installation', 'docs/installation.md'), ('Data sources', 'docs/data_sources.md'), ('Reaction–map matching', 'docs/reaction_map_matching.md'), ('Methodology', 'docs/methodology.md'), ('Layout evaluation', 'docs/layout_evaluation.md'), ('Limitations', 'docs/limitations.md'), ('Third-party notices', 'THIRD_PARTY_NOTICES.md'), ('Atlas data layout', 'data/README.md')]))
    s7 = sec('Documentation', '<div class="grid">' + cards + '</div>')
    d = ROOT / 'layout_atlas' / 'results' / 'about'
    d.mkdir(parents=True, exist_ok=True)
    ui.write(d / 'index.html', 'About / Provenance', s1 + s2 + s3 + s4 + s5 + s5b + s6 + s7, section='about', lead=b('Purpose, Atlas sources, matching defaults and licensing for Open Meta Maps.'))

def generate():
    home()
    about()
    return dict(status='generated', registry=str(REG.relative_to(ROOT)))
if __name__ == '__main__':
    print(generate())
